#!/usr/bin/env python3
"""Single editorial source of the GDC Metadata manual (RO / EN / ES).
Edit text HERE only; `scripts/build_manual.sh` turns it into the three PDFs (tools/make_manual.swift) and the web guide.
Inline markup: **bold** = real UI names, `code` = file names / commands. Image ids map to captures taken from the app (synthetic data only)."""
import json, sys
B = []
def h1(i, ro, en, es): B.append({"t": "h1", "id": i, "x": {"ro": ro, "en": en, "es": es}})
def h2(ro, en, es): B.append({"t": "h2", "x": {"ro": ro, "en": en, "es": es}})
def p(ro, en, es): B.append({"t": "p", "x": {"ro": ro, "en": en, "es": es}})
def note(kind, ro, en, es): B.append({"t": kind, "x": {"ro": ro, "en": en, "es": es}})
def steps(*items): B.append({"t": "steps", "items": [{"ro": a, "en": b, "es": c} for a, b, c in items]})
def lst(*items): B.append({"t": "list", "items": [{"ro": a, "en": b, "es": c} for a, b, c in items]})
def img(i, ro, en, es): B.append({"t": "img", "id": i, "x": {"ro": ro, "en": en, "es": es}})
def table(head, *rows): B.append({"t": "table", "head": [{"ro": a, "en": b, "es": c} for a, b, c in head], "rows": [[{"ro": a, "en": b, "es": c} for a, b, c in r] for r in rows]})

TITLE = {"ro": "Manual de utilizare", "en": "User manual", "es": "Manual de usuario"}
SUB = {"ro": "Metadate din clipuri multi-cameră, direct în Media Pool din DaVinci Resolve", "en": "Multi-camera clip metadata, straight into the DaVinci Resolve Media Pool", "es": "Metadatos de clips multicámara, directos al Media Pool de DaVinci Resolve"}
