CONTENTS = {"ro": "Cuprins", "en": "Contents", "es": "Índice"}
WHO = {"ro": "Pentru un editor sau colorist care deschide aplicația prima dată. Toate capturile folosesc date sintetice.", "en": "For an editor or colorist opening the app for the first time. All screenshots use synthetic data.", "es": "Para un editor o colorista que abre la app por primera vez. Todas las capturas usan datos sintéticos."}

